const raw = $input.first().json;
// Support input whether direct payload, nested in body, or from a test runner
const data = (raw.body && typeof raw.body === 'object') ? raw.body : raw;

const cleanStr = (val) => {
  if (val === null || val === undefined) return '';
  return String(val).trim();
};

const orgName = cleanStr(data.organization_name);
const rawWebsite = cleanStr(data.website);
let website = rawWebsite;
if (website && !/^https?:\/\//i.test(website)) {
  website = 'https://' + website;
}

const linkedin = cleanStr(data.linkedin_url);
const orgType = cleanStr(data.organization_type);
const city = cleanStr(data.city);
const state = cleanStr(data.state);
const country = cleanStr(data.country);
const userNotes = cleanStr(data.user_notes);

// Build location summary
const locationParts = [city, state, country].filter(Boolean);
const location = locationParts.length > 0 ? locationParts.join(', ') : 'Location not specified';

// Identify synthetic test fixture
const isSynthetic = /example\.(com|org|net)/i.test(website) || 
                    /test|synthetic|mock|stealthco/i.test(orgName) || 
                    Boolean(data.test_fixture);

if (!orgName) {
  return [{
    json: {
      isValid: false,
      errorCode: 'MISSING_REQUIRED_FIELD',
      errorMessage: 'Field organization_name is required and cannot be empty.',
      test_fixture: isSynthetic,
      input: {
        organization_name: '',
        website: website || 'Not provided',
        linkedin_url: linkedin || 'Not provided',
        organization_type: orgType || 'Not specified',
        location: location,
        user_notes: userNotes || 'None'
      }
    }
  }];
}

return [{
  json: {
    isValid: true,
    test_fixture: isSynthetic,
    input: {
      organization_name: orgName,
      website: website || 'Not provided',
      linkedin_url: linkedin || 'Not provided',
      organization_type: orgType || 'Not specified',
      city: city || '',
      state: state || '',
      country: country || '',
      location: location,
      user_notes: userNotes || 'None'
    }
  }
}];

const item = $input.first().json;
const inp = item.input;
const today = new Date().toISOString().split('T')[0];

const prompt = `You are an objective B2B prospect researcher. Your task is to gather factual, publicly verified information about the target organization.

TARGET ORGANIZATION:
- Name: ${inp.organization_name}
- Official Website: ${inp.website}
- LinkedIn: ${inp.linkedin_url}
- Declared Type: ${inp.organization_type}
- Location: ${inp.location}
- User Notes: ${inp.user_notes}

GROUNDING & RESEARCH RULES:
1. Research publicly available information using Google Search and official domains.
2. Ground every factual claim in verifiable public sources. Cite source URLs for every key piece of information.
3. NEVER fabricate or extrapolate: programs, startup counts, portfolio metrics, funding numbers, client names, or statistics.
4. If a piece of information cannot be verified from public sources, write "Not found" or "Not publicly verified". Do not guess.
5. Identify publicly available contact roles/departments (e.g. "Head of Incubation", "Program Director", "CTO", "Partnerships Lead"). DO NOT guess individual private emails or personal phone numbers. If no public role is verified, return ["Relevant contact not publicly verified"].
6. Output MUST be valid JSON adhering strictly to the schema below. Do not wrap in commentary.

REQUIRED JSON SCHEMA:
{
  "organization": {
    "name": "${inp.organization_name}",
    "website": "${inp.website !== 'Not provided' ? inp.website : 'Official website URL or Not found'}",
    "type": "Incubator/Accelerator | Startup | Enterprise/SME | Government/Academic",
    "location": "${inp.location}"
  },
  "description": "2-3 sentences summarizing what the organization does, verified from public sources.",
  "focus_areas": ["List of core focus areas, sectors, or domains"],
  "industries": ["Industries served"],
  "programs": ["Names of verified programs, cohorts, initiatives, or products"],
  "technology_focus": ["Verified technologies, tech stacks, or domains e.g. AI/ML, Cloud, IoT, Web"],
  "relevant_activities": ["Recent verified initiatives, hackathons, batch launches, or press releases"],
  "partnership_signals": ["Verified signs of external collaboration, ecosystem partners, or tech partnerships"],
  "relevant_contact_roles": ["Publicly verified job titles/roles suitable for technology outreach"],
  "sources": ["List of public URLs where information was verified"],
  "research_date": "${today}"
}`;

return [{
  json: {
    ...item,
    gemini_prompt: prompt
  }
}];

const item = $input.first().json;
const valNode = $('VALIDATE_Input').first().json;
const rawInput = item.input || valNode.input || {};
const isSynthetic = item.test_fixture ?? valNode.test_fixture ?? false;
const today = new Date().toISOString().split('T')[0];

// Handle Gemini response from langchain node or direct output
let geminiText = '';
if (item.response && typeof item.response === 'string') {
  geminiText = item.response;
} else if (item.text && typeof item.text === 'string') {
  geminiText = item.text;
} else if (typeof item === 'string') {
  geminiText = item;
} else if (item.content && typeof item.content === 'string') {
  geminiText = item.content;
} else {
  // If response is already an object
  if (item.organization && item.description) {
    return [{
      json: {
        input: rawInput,
        test_fixture: isSynthetic,
        structured_research: item,
        research_status: 'VERIFIED'
      }
    }];
  }
}

// Extract JSON from potential markdown fences
let parsed = null;
if (geminiText) {
  try {
    const jsonMatch = geminiText.match(/```(?:json)?\s*([\s\S]*?)\s*```/) || [null, geminiText];
    const cleanJson = (jsonMatch[1] || geminiText).trim();
    parsed = JSON.parse(cleanJson);
  } catch (e) {
    parsed = null;
  }
}

// Fallback if parsing fails or response was empty/error
if (!parsed || typeof parsed !== 'object') {
  parsed = {
    organization: {
      name: rawInput.organization_name || 'Not provided',
      website: rawInput.website || 'Not publicly verified',
      type: rawInput.organization_type || 'Unknown',
      location: rawInput.location || 'Not publicly verified'
    },
    description: 'Limited public information could be verified for this organization.',
    focus_areas: [],
    industries: [],
    programs: [],
    technology_focus: [],
    relevant_activities: [],
    partnership_signals: [],
    relevant_contact_roles: ['Relevant contact not publicly verified'],
    sources: rawInput.website && rawInput.website !== 'Not provided' ? [rawInput.website] : [],
    research_date: today
  };
}

// Ensure all schema fields exist defensively
const structuredResearch = {
  organization: {
    name: parsed.organization?.name || rawInput.organization_name || 'Not provided',
    website: parsed.organization?.website || rawInput.website || 'Not publicly verified',
    type: parsed.organization?.type || rawInput.organization_type || 'Not publicly verified',
    location: parsed.organization?.location || rawInput.location || 'Not publicly verified'
  },
  description: parsed.description || 'Limited public information could be verified for this organization.',
  focus_areas: Array.isArray(parsed.focus_areas) ? parsed.focus_areas : [],
  industries: Array.isArray(parsed.industries) ? parsed.industries : [],
  programs: Array.isArray(parsed.programs) ? parsed.programs : [],
  technology_focus: Array.isArray(parsed.technology_focus) ? parsed.technology_focus : [],
  relevant_activities: Array.isArray(parsed.relevant_activities) ? parsed.relevant_activities : [],
  partnership_signals: Array.isArray(parsed.partnership_signals) ? parsed.partnership_signals : [],
  relevant_contact_roles: Array.isArray(parsed.relevant_contact_roles) && parsed.relevant_contact_roles.length > 0 
    ? parsed.relevant_contact_roles 
    : ['Relevant contact not publicly verified'],
  sources: Array.isArray(parsed.sources) ? parsed.sources : [],
  research_date: parsed.research_date || today
};

const desc = structuredResearch.description || '';
const isFallbackDesc = desc.toLowerCase().includes('limited public information') || desc.toLowerCase().includes('public description not found');
const hasSubstantialData = (!isFallbackDesc) && (structuredResearch.focus_areas.length > 0 || structuredResearch.programs.length > 0 || desc.length > 50);

return [{
  json: {
    input: rawInput,
    test_fixture: isSynthetic,
    structured_research: structuredResearch,
    research_status: hasSubstantialData ? 'VERIFIED' : 'INSUFFICIENT_DATA'
  }
}];

const item = $input.first().json;
const structNode = $('STRUCTURE_Research').first().json;
const valNode = $('VALIDATE_Input').first().json;
const res = item.structured_research || structNode.structured_research;
const rawInput = item.input || valNode.input;
const isTestFixture = item.test_fixture ?? structNode.test_fixture ?? valNode.test_fixture;
const today = new Date().toISOString();

let claudeText = '';
if (item.response && typeof item.response === 'string') {
  claudeText = item.response;
} else if (item.text && typeof item.text === 'string') {
  claudeText = item.text;
} else if (typeof item === 'string') {
  claudeText = item;
} else if (item.content && typeof item.content === 'string') {
  claudeText = item.content;
}

let analysis = null;
if (claudeText) {
  try {
    const jsonMatch = claudeText.match(/```(?:json)?\s*([\s\S]*?)\s*```/) || [null, claudeText];
    const cleanJson = (jsonMatch[1] || claudeText).trim();
    analysis = JSON.parse(cleanJson);
  } catch (e) {
    analysis = null;
  }
}

// Fallback if Claude node was simulated or response was raw
if (!analysis || typeof analysis !== 'object') {
  const isInsuff = structNode.research_status === 'INSUFFICIENT_DATA';
  analysis = {
    fit_level: isInsuff ? 'INSUFFICIENT_DATA' : 'MEDIUM',
    fit_reasons: isInsuff 
      ? ['Insufficient public information available to verify commercial technology fit.']
      : ['Analysis generated based on available verified public profile data.'],
    relevant_services: isInsuff ? [] : ['Product Engineering', 'AI Development', 'Cloud Architecture'],
    recommended_offer: isInsuff ? 'Preliminary Discovery / Qualification' : 'Exploratory Technology Capabilities Consultation',
    value_proposition: isInsuff 
      ? 'Pending further direct discovery with organization leadership.'
      : `Supporting ${res.organization.name} with dedicated software engineering and AI capabilities.`,
    personalization_angle: isInsuff
      ? 'Requesting initial discussion on their current technology objectives and roadmap.'
      : `Focus on their activities in ${res.focus_areas.join(', ') || 'technology innovation'}.`,
    recommended_contact_role: res.relevant_contact_roles[0] || 'Relevant contact not publicly verified.',
    suggested_cta: isInsuff
      ? 'Introductory query to establish correct point of contact.'
      : 'Invite for a brief 15-minute technology alignment conversation.',
    potential_objections: isInsuff 
      ? ['Unknown project requirements or operational scale']
      : ['Existing internal tech team or development partners', 'Budget allocation'],
    confidence: isInsuff ? 'LOW' : 'MEDIUM'
  };
}

// Construct standard final output object per contract
const finalOutput = {
  prospect_profile: {
    organization_name: res.organization.name,
    website: res.organization.website,
    type: res.organization.type,
    location: res.organization.location,
    description: res.description,
    focus_areas: res.focus_areas,
    industries: res.industries,
    programs: res.programs,
    technology_focus: res.technology_focus
  },
  research: {
    relevant_activities: res.relevant_activities,
    partnership_signals: res.partnership_signals,
    relevant_contact_roles: res.relevant_contact_roles,
    sources: res.sources,
    research_date: res.research_date
  },
  venturelyhub_analysis: {
    fit_level: analysis.fit_level || 'MEDIUM',
    fit_reasons: Array.isArray(analysis.fit_reasons) ? analysis.fit_reasons : [String(analysis.fit_reasons)],
    relevant_services: Array.isArray(analysis.relevant_services) ? analysis.relevant_services : [],
    recommended_offer: analysis.recommended_offer || 'Technology Partnership Discussion',
    value_proposition: analysis.value_proposition || '',
    personalization_angle: analysis.personalization_angle || '',
    recommended_contact_role: analysis.recommended_contact_role || 'Relevant contact not publicly verified.',
    suggested_cta: analysis.suggested_cta || '',
    potential_objections: Array.isArray(analysis.potential_objections) ? analysis.potential_objections : [],
    confidence: analysis.confidence || 'MEDIUM'
  },
  metadata: {
    workflow_name: 'VenturelyHub Prospect Intelligence',
    processed_at: today,
    status: 'SUCCESS',
    test_fixture: Boolean(isTestFixture)
  }
};

return [{ json: finalOutput }];

const raw = $input.first().json;
const now = new Date();
const nowIso = now.toISOString();

// Deterministic unique execution ID
const datePrefix = nowIso.split('T')[0].replace(/-/g, '');
const randomSuffix = Math.floor(1000 + Math.random() * 9000);
const executionId = `EXEC-P1-${datePrefix}-${randomSuffix}`;

const profile = raw.prospect_profile || {};
const research = raw.research || {};
const analysis = raw.venturelyhub_analysis || {};

const orgName = profile.organization_name || '';
const website = profile.website || '';
const isSynthetic = /example\.(com|org|net)/i.test(website) || 
                    /test|synthetic|mock|stealthco/i.test(orgName) || 
                    Boolean(raw.metadata?.test_fixture);

const rawOutputJson = JSON.stringify(raw);

const sheetRow = {
  execution_id: executionId,
  created_at: nowIso,
  workflow_name: "VenturelyHub Prospect Intelligence",
  phase: "Phase 1 - Prospect Intelligence",
  status: raw.metadata?.status || "SUCCESS",
  test_fixture: isSynthetic,
  organization_name: orgName || "Not provided",
  fit_level: analysis.fit_level || "INSUFFICIENT_DATA",
  recommended_offer: analysis.recommended_offer || "",
  recommended_contact_role: analysis.recommended_contact_role || "",
  research_date: research.research_date || nowIso.split('T')[0],
  raw_output_json: rawOutputJson,
  error_message: ""
};

return [{
  json: {
    ...sheetRow,
    _original_output: raw
  }
}];

const item = $input.first().json;
const original = item._original_output || $('FORMAT_Output').first().json;
return [{
  json: original
}];

const item = $input.first().json;
const inp = item.input || {};
const now = new Date();
const nowIso = now.toISOString();

const datePrefix = nowIso.split('T')[0].replace(/-/g, '');
const randomSuffix = Math.floor(1000 + Math.random() * 9000);
const eventId = `EVT-P1-${datePrefix}-${randomSuffix}`;

const isSynthetic = /example\.(com|org|net)/i.test(inp.website || '') || 
                    /test|synthetic|mock|stealthco/i.test(inp.organization_name || '') ||
                    Boolean(item.test_fixture);

const errorObj = {
  error: {
    code: item.errorCode || 'VALIDATION_ERROR',
    message: item.errorMessage || 'Prospect input validation failed.'
  },
  prospect_profile: {
    organization_name: inp.organization_name || 'Not provided',
    website: inp.website || 'Not provided',
    type: inp.organization_type || 'Not specified',
    location: inp.location || 'Not specified',
    description: 'Validation failed before research could begin.',
    focus_areas: [],
    industries: [],
    programs: [],
    technology_focus: []
  },
  research: {
    relevant_activities: [],
    partnership_signals: [],
    relevant_contact_roles: ['Relevant contact not publicly verified.'],
    sources: [],
    research_date: nowIso.split('T')[0]
  },
  venturelyhub_analysis: {
    fit_level: 'INSUFFICIENT_DATA',
    fit_reasons: ['Validation error: ' + (item.errorMessage || 'Missing required organization name.')],
    relevant_services: [],
    recommended_offer: 'None',
    value_proposition: 'None',
    personalization_angle: 'None',
    recommended_contact_role: 'Relevant contact not publicly verified.',
    suggested_cta: 'None',
    potential_objections: [],
    confidence: 'LOW'
  },
  metadata: {
    workflow_name: 'VenturelyHub Prospect Intelligence',
    processed_at: nowIso,
    status: 'VALIDATION_FAILED',
    test_fixture: isSynthetic
  }
};

const systemEventRow = {
  event_id: eventId,
  created_at: nowIso,
  workflow_name: 'VenturelyHub Prospect Intelligence',
  phase: 'Phase 1 - Prospect Intelligence',
  event_type: 'VALIDATION_FAILURE',
  status: 'VALIDATION_FAILED',
  test_fixture: isSynthetic,
  message: item.errorMessage || 'Validation failed: organization_name required.',
  raw_event_json: JSON.stringify(errorObj),
  _original_error: errorObj
};

return [{ json: systemEventRow }];

const item = $input.first().json;
const original = item._original_error || $('FORMAT_ErrorOutput').first().json;
return [{
  json: original
}];
